import{_ as a,o,c as t,a2 as s}from"./chunks/framework.LX5S0jbT.js";const u=JSON.parse('{"title":"会话与上下文","description":"","frontmatter":{},"headers":[],"relativePath":"zh/sessions.md","filePath":"zh/sessions.md"}'),i={name:"zh/sessions.md"};function d(c,e,n,r,p,h){return o(),t("div",null,[...e[0]||(e[0]=[s(`<h1 id="会话与上下文" tabindex="-1">会话与上下文 <a class="header-anchor" href="#会话与上下文" aria-label="Permalink to &quot;会话与上下文&quot;">​</a></h1><p>Pi 将对话保存为会话（session）。该会话的活跃分支为下一次模型请求提供对话历史。使用会话命令可以继续工作、探索其他分支，或减少发送给模型的历史量。</p><h2 id="继续或切换会话" tabindex="-1">继续或切换会话 <a class="header-anchor" href="#继续或切换会话" aria-label="Permalink to &quot;继续或切换会话&quot;">​</a></h2><p>Pi 会自动保存会话，除非使用 <code>--no-session</code> 启动。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pi</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --continue</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pi</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --resume</span></span></code></pre></div><p><code>--continue</code> 打开当前工作目录最近的会话。<code>--resume</code> 打开会话选择器。在交互模式中，<code>/resume</code> 打开同一个选择器，<code>/new</code> 开启新会话。</p><p>使用 <code>/name</code> 或 <code>--name</code> 为会话指定一个易于识别的名称。运行 <code>/session</code> 可查看当前会话文件、ID、消息数、token 用量和费用。</p><p>会话选择器支持搜索、重命名和删除会话，还可以显示路径、更改排序，以及只显示已命名的会话。其快捷键见<a href="./keybindings.html#sessions">快捷键</a>。</p><h2 id="选择分支方式" tabindex="-1">选择分支方式 <a class="header-anchor" href="#选择分支方式" aria-label="Permalink to &quot;选择分支方式&quot;">​</a></h2><p>Pi 将条目存储为树，因此返回较早的位置不会抹掉你离开的分支。</p><table tabindex="0"><thead><tr><th>操作</th><th>结果</th><th>适用场景</th></tr></thead><tbody><tr><td><code>/tree</code></td><td>在当前会话文件内移动</td><td>相关的备选方案应放在一起</td></tr><tr><td><code>/fork</code></td><td>从较早的用户消息创建新会话</td><td>备选方案应成为独立的工作</td></tr><tr><td><code>/clone</code></td><td>将活跃分支复制到新会话</td><td>需要当前状态的独立副本时</td></tr></tbody></table><p>在 <code>/tree</code> 中，选中一条用户消息可将其文本放回编辑器。编辑并提交即可创建另一个分支。选中助手响应或其他条目则从该条目之后继续，编辑器为空。</p><p>离开一个分支时，Pi 可以对它进行摘要，并将该摘要附加到你进入的分支上。这样既保留了被放弃路径中的相关内容，又不必包含其中的每条消息。</p><p>持久化的树和条目类型见<a href="./session-format.html">会话文件格式</a>。</p><p><a id="manage-conversation-context"></a></p><h2 id="管理对话上下文" tabindex="-1">管理对话上下文 <a class="header-anchor" href="#管理对话上下文" aria-label="Permalink to &quot;管理对话上下文&quot;">​</a></h2><p>模型接收的是活跃分支，而不是会话文件中的所有分支。Pi 将这段历史与系统提示词、发现的上下文文件、可用工具和已加载的技能（skill）描述组合在一起。<a href="./how-pi-works.html#context">Pi 的工作原理</a>描述了这些输入如何组装。</p><p>底部状态栏显示当前上下文用量。当活跃上下文接近模型上限时，Pi 通常会自动压缩（compaction）较旧的历史。压缩会添加一条摘要并保留最近的消息，但不会删除原始会话条目。</p><p>运行 <code>/compact</code> 可手动压缩。当摘要需要保留特定主题或决策时，可以附加指令。通过<a href="./settings.html#compaction">设置</a>配置自动压缩和保留的历史。</p><p>如果提供商（provider）不可用或无法接受摘要请求，压缩可能失败。解决提供商问题后再次运行 <code>/compact</code>。禁用自动压缩不会禁用手动命令。</p><p>阈值、保留边界、分支摘要行为和扩展钩子见<a href="./compaction.html">压缩参考</a>。</p><h2 id="控制会话存储" tabindex="-1">控制会话存储 <a class="header-anchor" href="#控制会话存储" aria-label="Permalink to &quot;控制会话存储&quot;">​</a></h2><p>默认情况下，Pi 将会话存储在 <code>~/.pi/agent/sessions/</code> 下，按工作目录分组。使用 <code>--session-dir</code>、<code>PI_CODING_AGENT_SESSION_DIR</code> 或 <code>sessionDir</code> 设置可选择其他位置。CLI 选项的优先级最高。</p><p>临时运行使用 <code>--no-session</code>。临时会话在 Pi 退出后无法恢复。</p><p>已知会话路径或 ID 时使用 <code>--session</code>。使用 <code>--fork</code> 可在交互模式开始前从现有会话创建新会话。</p><h2 id="导出或分享会话" tabindex="-1">导出或分享会话 <a class="header-anchor" href="#导出或分享会话" aria-label="Permalink to &quot;导出或分享会话&quot;">​</a></h2><p>使用 <code>/export</code> 可将当前会话导出为 HTML 或 JSONL。使用 <code>/share</code> 可上传会话并获得查看链接。默认情况下，已配置 Radius 认证时 Pi 使用 Radius artifact，否则使用私有的 GitHub gist。将 <a href="./settings.html#sessions-and-context"><code>sessionShareDestination</code></a> 设为 <code>gist</code> 或 <code>radius</code> 可强制指定目的地。</p><p>导出或分享之前请先检查会话内容。其中可能包含提示词、模型响应、工具参数、命令输出、文件内容和扩展消息。</p><h2 id="报告-bug" tabindex="-1">报告 bug <a class="header-anchor" href="#报告-bug" aria-label="Permalink to &quot;报告 bug&quot;">​</a></h2><p>运行 <code>/bug [description]</code> 可为 Pi 开发者准备一份私密报告。你可以包含会话记录、省略它，或让当前模型总结问题。请检查记录或生成的摘要，因为其中可能包含敏感的对话数据。</p><p>报告包含环境和提供商配置（不含凭据值），以及记录的错误诊断。通过 <code>radius.pi.dev</code> 上传，或导出同一报告的 zip 自行检查和分享。上传无需登录；Radius 认证会将报告归属到你的账户，便于开发者跟进。如果上传失败，Pi 会提供导出 zip 的选项。</p>`,31)])])}const m=a(i,[["render",d]]);export{u as __pageData,m as default};
